class FreeFee implements FeePolicy {
    public int fee() { return 0; }
}
// 결제는 배송비 역할을 받아 그 계산을 맡겨요.
class Checkout {
    private final FeePolicy policy;
    Checkout(FeePolicy policy) { this.policy = policy; }
    int total(int amount) { return amount + policy.fee(); }
}

public class Main {
    public static void main(String[] args) {
        Checkout checkout = new Checkout(new StandardFee());
        System.out.println(checkout.total(10000));
    }
}

class Account {
    private int balance;
    Account(int opening) {
        // 잘못된 시작 상태를 만들기 전에 실패를 알려요.
        if (opening < 0) throw new IllegalArgumentException("negative balance");
        balance = opening;
    }
    public int balance() { return balance; }
}

public class Main {
    public static void main(String[] args) {
        try {
            Account account = new Account(-1);
            System.out.println(account.balance());
            System.out.println("after");
        } catch (IllegalArgumentException error) {
            System.out.println("invalid");
        }
    }
}

class Payment {
    static void pay(int amount) {
        if (amount <= 0) throw new IllegalArgumentException("positive amount required");
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            Payment.pay(-1);
            System.out.println("success");
        } catch (IllegalArgumentException error) {
            System.out.println("failed");
        } finally {
            System.out.println("closed");
        }
        System.out.println("after");
    }
}

